import{_ as t,o as r,c as a,a2 as o}from"./chunks/framework.BXzK3EA4.js";const i="/assets/318_d8abc305-b66b-4032-bb11-ca701f76b3c1.BneSYAO1.png",s="/assets/319_1dabe839-bb69-43b8-90a0-ddab2c81cdd9.DOo4oXg_.png",d="/assets/320_6a21f2f1-2033-480c-a094-743e1bc6d1f0.Bp5r7eGB.png",y=JSON.parse('{"title":"How to Find Purchased Products","description":"","frontmatter":{"title":"How to Find Purchased Products"},"headers":[],"relativePath":"operations-knowledge-base/presales-support/how-to-find-purchased-products.md","filePath":"operations-knowledge-base/presales-support/how-to-find-purchased-products.md","lastUpdated":1794292919000}'),n={name:"operations-knowledge-base/presales-support/how-to-find-purchased-products.md"};function l(c,e,h,u,p,g){return r(),a("div",null,[...e[0]||(e[0]=[o('<h2 id="_1-overview" tabindex="-1">1. Overview <a class="header-anchor" href="#_1-overview" aria-label="Permalink to &quot;1. Overview&quot;">​</a></h2><p>When you need to manage your purchased cloud services, such as Dedicated, Bare Metal Cloud, or VPS, or check product status and renewal information, you can quickly locate your products in the RakSmart Client Area using the following three methods:</p><ul><li>Quick Search - Search directly using the hostname or primary IP address</li><li>Homepage Shortcut - View products through “My Orders” or “My Services”</li><li>Product Navigation - Filter products by type, region, or status</li></ul><p>Below are the detailed steps for each method.</p><hr><h2 id="method-1-quick-search-fastest" tabindex="-1">Method 1: Quick Search (Fastest) <a class="header-anchor" href="#method-1-quick-search-fastest" aria-label="Permalink to &quot;Method 1: Quick Search (Fastest)&quot;">​</a></h2><p>If you remember the server hostname or primary IP address, you can use this method to quickly locate your machine.</p><h3 id="steps" tabindex="-1">Steps <a class="header-anchor" href="#steps" aria-label="Permalink to &quot;Steps&quot;">​</a></h3><ol><li><p><strong>Log in to the RakSmart Client Area.</strong></p></li><li><p>Locate the search bar in the top-right corner of the page (the input field labeled “Search”).</p><p><img src="'+i+'" alt=""></p></li><li><p>Enter the primary IP address or hostname of your server.</p><ul><li><p>For example:</p><ul><li>192.168.1.100</li><li>sv-xxxxx</li></ul></li></ul></li><li><p>The system will automatically display matching product orders.</p></li><li><p>Click the corresponding order to enter the product page.</p></li></ol><h3 id="suitable-for" tabindex="-1">Suitable For <a class="header-anchor" href="#suitable-for" aria-label="Permalink to &quot;Suitable For&quot;">​</a></h3><ul><li>When you remember the IP address or hostname</li><li>When you need quick access to a specific server</li></ul><hr><h2 id="method-2-find-products-from-the-client-area-homepage" tabindex="-1">Method 2: Find Products from the Client Area Homepage <a class="header-anchor" href="#method-2-find-products-from-the-client-area-homepage" aria-label="Permalink to &quot;Method 2: Find Products from the Client Area Homepage&quot;">​</a></h2><p>If you have just logged in to the client area, you can quickly view active services through the homepage shortcuts.</p><h3 id="view-via-my-orders-current-orders" tabindex="-1">View via My Orders - Current Orders <a class="header-anchor" href="#view-via-my-orders-current-orders" aria-label="Permalink to &quot;View via My Orders - Current Orders&quot;">​</a></h3><ol><li><p>Log in and go to the Customer Center.</p><p><img src="'+s+'" alt=""></p></li><li><p>Locate the “My Orders” section.</p></li><li><p>Check “Current Orders” to see a list of active orders.</p></li><li><p>From the list, you can：</p><ul><li>Click the product type (e.g., Dedicated) to open the product details page</li><li>Or click “My Services” to view all active services</li></ul></li></ol><h3 id="suitable-for-1" tabindex="-1">Suitable For <a class="header-anchor" href="#suitable-for-1" aria-label="Permalink to &quot;Suitable For&quot;">​</a></h3><ul><li>Quickly viewing all active products</li><li>When you do not remember the IP address or hostname</li></ul><hr><h2 id="method-3-find-products-via-product-navigation-most-comprehensive" tabindex="-1">Method 3: Find Products via Product Navigation (Most Comprehensive) <a class="header-anchor" href="#method-3-find-products-via-product-navigation-most-comprehensive" aria-label="Permalink to &quot;Method 3: Find Products via Product Navigation (Most Comprehensive)&quot;">​</a></h2><p>If you need to filter products by type, region, or status, this method is recommended.</p><h3 id="_1-enter-product-management" tabindex="-1">1. Enter Product Management <a class="header-anchor" href="#_1-enter-product-management" aria-label="Permalink to &quot;1. Enter Product Management&quot;">​</a></h3><p>In the left navigation menu, find “My Products”, then choose the corresponding product type based on your purchase:</p><ul><li><p>Dedicated</p></li><li><p>Bare Metal Cloud</p></li><li><p>VPS</p></li><li><p><img src="'+d+'" alt=""></p></li></ul><h3 id="_2-filter-by-region" tabindex="-1">2. Filter by Region <a class="header-anchor" href="#_2-filter-by-region" aria-label="Permalink to &quot;2. Filter by Region&quot;">​</a></h3><p>After entering the product page, you will see region filtering options.</p><table tabindex="0"><thead><tr><th>Region</th><th>Available Locations</th></tr></thead><tbody><tr><td>Americas</td><td>Silicon Valley, Los Angeles, Seattle, etc.</td></tr><tr><td>Asia</td><td>Singapore, Hong Kong, Japan, Korea, etc.</td></tr><tr><td>Europe</td><td>Frankfurt, etc.</td></tr></tbody></table><p>Select the corresponding region to view all servers in that location.</p><h3 id="_3-filter-by-status" tabindex="-1">3. Filter by Status <a class="header-anchor" href="#_3-filter-by-status" aria-label="Permalink to &quot;3. Filter by Status&quot;">​</a></h3><p>After selecting a region, you can further filter machines by status.</p><table tabindex="0"><thead><tr><th>Status</th><th>Description</th></tr></thead><tbody><tr><td>All</td><td>Displays all machines regardless of status</td></tr><tr><td>Active</td><td>Servers currently running normally</td></tr><tr><td>Pending</td><td>New orders or changes awaiting approval</td></tr><tr><td>Suspended</td><td>Suspended due to unpaid invoices or other reasons</td></tr><tr><td>Terminated</td><td>Deleted or expired services</td></tr><tr><td>Cancelled</td><td>Orders that have been cancelled</td></tr></tbody></table><h3 id="_4-view-product-list" tabindex="-1">4. View Product List <a class="header-anchor" href="#_4-view-product-list" aria-label="Permalink to &quot;4. View Product List&quot;">​</a></h3><p>After applying filters, the page will display a list of matching products, including:</p><ul><li><strong>Product/Service</strong> - Product configuration details</li><li><strong>Hostname</strong> - Server hostname</li><li><strong>IP Address</strong> - Server IP address (for some products)</li><li><strong>Pricing</strong> - Product price</li><li><strong>Next Due Date</strong> - Renewal date</li><li><strong>Status</strong> - Current service status</li><li><strong>Automatic Renewal</strong> - Whether automatic renewal is enabled</li></ul><p>Click a product to enter the management panel, where you can perform operations such as:</p><ul><li>Reinstalling the operating system</li><li>Restarting the server</li><li>Viewing monitoring information</li></ul><hr><h2 id="product-search-path-summary" tabindex="-1">Product Search Path Summary <a class="header-anchor" href="#product-search-path-summary" aria-label="Permalink to &quot;Product Search Path Summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Product Type</th><th>Navigation Path</th></tr></thead><tbody><tr><td>Dedicated</td><td>My Products → Dedicated → Filter by region/status</td></tr><tr><td>Bare Metal Cloud</td><td>My Products → Bare Metal Cloud → Filter by region/status</td></tr><tr><td>VPS</td><td>My Products → VPS → Filter by region/status</td></tr><tr><td>All Active Products</td><td>Client Area Homepage → My Services</td></tr><tr><td>Current Orders</td><td>Customer Center → My Orders → Current Orders</td></tr></tbody></table><hr><h2 id="frequently-asked-questions" tabindex="-1">Frequently Asked Questions <a class="header-anchor" href="#frequently-asked-questions" aria-label="Permalink to &quot;Frequently Asked Questions&quot;">​</a></h2><p><strong>Q: Why can’t I see any machines in Product Management?</strong><strong>A:</strong> Please check the following:</p><ol><li>Make sure you selected the correct product type.</li><li>Confirm that the region filter includes the location of your server.</li><li>Check whether the status filter is set to “All” or “Active”.</li><li>Ensure that the logged-in account is the owner of the product.</li></ol><p><strong>Q: Why does nothing appear after entering an IP address in the search bar?</strong><strong>A:</strong> Please confirm:</p><ol><li>The IP address is entered correctly.</li><li>The IP belongs to a product under the currently logged-in account.</li></ol><p><strong>Q: What does “Pending” status mean for my server?</strong><strong>A:</strong> It means your newly purchased server is currently being prepared or installed. Once the setup is complete and approved, the status will change to “Active”.</p><p><strong>Q: What is the difference between Dedicated and Bare Metal Cloud?</strong><strong>A:</strong><strong>Dedicated</strong> refers to a traditional physical server. <strong>Bare Metal Cloud</strong> refers to a physical server with cloud-style features and management capabilities.</p><p>These two product types are listed under separate menus in “My Products”, so please choose the appropriate section based on the product you purchased.</p>',48)])])}const b=t(n,[["render",l]]);export{y as __pageData,b as default};
